/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Candidate, ReviewCandidate
 *   Functions: release, key, comparison, candidate, group, view, applied, mount, unfold, subset,
 *              reviewCandidate, reviewView, mountReview
 *   Constants: importId, viewerId, reviewTracks
 * Tests
 *   - the folded list gives each release its status, label, date and track count, and says how a non-matching one differs
 *   - the tie view repeats only the values that differ, here the disc and track order, and needs one release or none
 *   - the release applied for this run is marked and cannot be chosen again, an applied none disables none, and an earlier run's choice marks nothing
 *   - files whose duration or disc number is unknown are disclosed beside the releases, never counted as agreement, and nothing is said while all are known
 *   - one matching group of a partial comparison is offered in a region with the single-choice heading, every proposal value and Use none of these; the partial-comparison line is shown
 *   - a release applied as a preselection stays choosable when a re-rank leaves a tie, so it can be confirmed as the choice
 *   - a tie from a partial comparison keeps the several-releases heading and says not every release was compared; without a choice the line stands beside the folded list
 *   - groups that differ only by the MusicBrainz artist or label they credit show each ID beside the names
 *   - a release reporting front artwork shows it once through the protected preview of this import: in the tie view, else in the folded list once opened
 *   - previews load two at a time in the order shown, and one that fails is tried once more after two seconds and then hidden
 *   - an iTunes-only candidate is marked as such, and as not checked against MusicBrainz when it was not, and previews through its own encoded key
 *   - an existing-Album review candidate shows the members it pairs, the missing-file rows it adds, tracks left out and members no track can pair with
 *   - a review tie, the offered single choice, unverified releases and the disclosures speak of the Album's tracks; an import keeps its file wording
 *   - a review release first found through a track title is marked so in the tie view, the offered single choice and the folded list; another release and any import candidate are not
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { CandidateChooser } from './CandidateChooser';
import type { ImportLookupView, ReviewLookupView } from './importLookupApi';

/**
 * The candidate chooser on its own: each candidate's status line and differences in the folded list, which values the tie view
 * repeats, how the applied release and an applied none are marked, the disclosure of files whose duration or disc number is
 * unknown, the optional choice a lone matching release of a partial comparison offers and where a partial comparison is said. All
 * names and identifiers are synthetic.
 */
type Candidate = ImportLookupView['candidates'][number];
const release = (n: number) => `0000000b-0000-4000-8000-00000000000${n}`;
const key = (n: number) => `musicbrainz:${release(n)}`;
const comparison = (differences: ('trackCount' | 'discCount' | 'duration')[] = []) => ({ trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 2 }, differences, unknownLocalDurations: 0, unknownCandidateDurations: 0 });
const candidate = (n: number, extra: Partial<Candidate> = {}): Candidate => ({ key: key(n), releaseId: release(n), source: 'musicbrainz', notChecked: false, status: 'matching', title: `Synthetic Album ${n}`, artist: 'Synthetic Lead', label: `Label ${n}`,
  catalogNumber: null, barcode: null, country: null, date: { year: 2021, month: 5, day: null }, formats: [], trackCount: 2, comparison: comparison(), groupKey: String(n).repeat(64), artistMismatch: false, artwork: false, ...extra });
const group = (n: number, tracks: [number, number, string][]) => ({ groupKey: String(n).repeat(64), representativeKey: key(n), memberKeys: [key(n)], proposal: { albumTitle: 'Synthetic Album',
  artists: [{ name: 'Synthetic Lead', role: 'primary' as const, joinPhrase: null, musicBrainzId: null as string | null }], label: 'Label', labelMusicBrainzId: null as string | null, releaseDate: null, tracks: tracks.map(([discNumber, trackNumber, title]) => ({ discNumber, trackNumber, title })) } });
const view = (extra: Partial<ImportLookupView> = {}): ImportLookupView => ({ run: 2, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'tags', submitted: null }, candidates: [], groups: [],
  preselection: null, disclosure: null, applied: null, staleFiles: [], needsAnswer: { tie: false, conflicts: [] }, blocking: false, itunes: 'notQueried', ...extra });
const applied = (run: number, candidateKey: string | null): ImportLookupView['applied'] => ({ run, candidateKey, releaseId: null, choice: candidateKey ? 'chosen' : 'none', basis: candidateKey ? 'chosen' : null,
  source: 'musicbrainz', notChecked: false, values: [], conflicts: [], flagged: [] });
const importId = 'aaaaaaaaaaaaaaaaaaaaaaaa', viewerId = 'bbbbbbbbbbbbbbbbbbbbbbbb';
function mount(lookup: ImportLookupView, disabled = false) { const onChoose = vi.fn(); render(<CandidateChooser projectId={importId} viewerId={viewerId} lookup={lookup} disabled={disabled} onChoose={onChoose} />); return onChoose; }
afterEach(cleanup);
/** Opens the folded list whose summary is `summary`, as the browser does when it is clicked. */
const unfold = (summary: HTMLElement) => { const details = summary.closest('details')!; act(() => { details.open = true; fireEvent(details, new Event('toggle')); }); };

test('the folded list gives each release its status, label, date and track count, and says how a non-matching one differs', () => {
  mount(view({ candidates: [candidate(1), candidate(2, { status: 'notMatching', groupKey: null, comparison: comparison(['discCount', 'duration']) }), candidate(3, { status: 'incomplete', label: null, date: null, trackCount: null, comparison: null }),
    candidate(4, { status: 'unverified', title: null, artist: null })] }));
  const [matching, differing, incomplete, unverified] = screen.getAllByRole('listitem').filter(item => item.querySelector('strong'));
  expect(within(matching).getByText('Matches these files · Label 1 · 2021-05 · 2 tracks')).toBeInTheDocument();
  expect(within(differing).getAllByRole('listitem').map(item => item.textContent)).toEqual(['Discs: — here, 2 on the release', 'Track durations differ']);
  expect(within(incomplete).getByText(/^Details could not be fetched/)).toBeInTheDocument();
  expect(unverified.querySelector('strong')!.textContent).toBe('—');
  expect(within(unverified).getByText(/^Not verified: some durations are unknown/)).toBeInTheDocument();
  // Missing evidence reads as a dash, never as an empty cell.
  expect([...matching.querySelectorAll('dd')].map(value => value.textContent)).toEqual(['—', '—', '—', '—']);
});

test('the tie view repeats only the values that differ, here the disc and track order, and needs one release or none', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First'], [1, 2, 'Second']]), group(2, [[1, 1, 'First'], [2, 1, 'Second']])], needsAnswer: { tie: true, conflicts: [] } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  const [first, second] = within(tie).getAllByRole('listitem');
  expect([...first.querySelectorAll('dt')].map(term => term.textContent)).toEqual(['Disc and track order', 'Barcode', 'Catalogue number', 'Country', 'Medium']);
  expect(second.querySelector('dd')!.textContent).toBe('1.1 First · 2.1 Second');
  // Each choice names the release it chooses.
  expect(within(second).getByRole('button', { name: 'Use this release' })).toHaveAccessibleDescription('Synthetic Album 2 · Synthetic Lead');
  fireEvent.click(within(tie).getByRole('button', { name: 'Use none of these' }));
  expect(onChoose).toHaveBeenCalledWith(null);
});

test('the release applied for this run is marked and cannot be chosen again, an applied none disables none, and an earlier run\'s choice marks nothing', () => {
  let onChoose = mount(view({ candidates: [candidate(1), candidate(2)], applied: applied(2, key(1)) }));
  expect(screen.getByRole('button', { name: 'Applied' })).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'Use this release' })); expect(onChoose).toHaveBeenCalledWith(key(2));
  expect(screen.getByRole('button', { name: 'Use none of these' })).toBeEnabled();
  cleanup();
  mount(view({ candidates: [candidate(1)], applied: applied(2, null) }));
  expect(screen.getByRole('button', { name: 'Use none of these' })).toBeDisabled();
  cleanup();
  onChoose = mount(view({ candidates: [candidate(1)], applied: applied(1, key(1)) }));
  expect(screen.queryByRole('button', { name: 'Applied' })).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Use this release' })); expect(onChoose).toHaveBeenCalledWith(key(1));
  cleanup();
  mount(view({ candidates: [candidate(1)] }), true);
  for (const button of screen.getAllByRole('button')) expect(button).toBeDisabled();
});

test('files whose duration or disc number is unknown are disclosed beside the releases, never counted as agreement, and nothing is said while all are known', () => {
  mount(view({ candidates: [candidate(1)], disclosure: { unknownLocalDurations: 2, unknownLocalDiscNumbers: 1, partialComparison: false } }));
  expect(screen.getByText('Files with an unknown duration: 2. They are not counted as agreeing with any release.')).toBeInTheDocument();
  expect(screen.getByText('Files with an unknown disc number: 1. They are not counted as agreeing with any release.')).toBeInTheDocument();
  cleanup();
  // A tie shows the disclosure where the choice is made.
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 3, partialComparison: false } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  expect(within(tie).getByText('Files with an unknown disc number: 3. They are not counted as agreeing with any release.')).toBeInTheDocument();
  expect(screen.queryByText(/unknown duration/)).not.toBeInTheDocument();
  cleanup();
  for (const disclosure of [null, { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false }]) {
    mount(view({ candidates: [candidate(1)], disclosure }));
    expect(screen.queryByText(/not counted as agreeing/)).not.toBeInTheDocument();
    cleanup();
  }
});

test('one matching group of a partial comparison is offered in a region with the single-choice heading, every proposal value and Use none of these; the partial-comparison line is shown', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2, { status: 'notMatching', groupKey: null, comparison: comparison(['duration']) })], groups: [group(1, [[1, 1, 'First'], [1, 2, 'Second']])],
    disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  const choice = screen.getByRole('region', { name: 'One release matches these files but was not applied, because not every release MusicBrainz found was compared. You can choose it, another release or none.' });
  expect(screen.getAllByRole('button', { name: 'Use none of these' })).toHaveLength(1);
  const [only] = within(choice).getAllByRole('listitem');
  // A single group shows every value it would write, since nothing differs from another group.
  expect([...only.querySelectorAll('dt')].map(term => term.textContent)).toEqual(['Title', 'Artists', 'Label', 'Release date', 'Disc and track order', 'Barcode', 'Catalogue number', 'Country', 'Medium']);
  expect(within(choice).getByText('Not every release MusicBrainz found was compared with these files, so a matching release may be missing from this list.')).toBeInTheDocument();
  fireEvent.click(within(only).getByRole('button', { name: 'Use this release' }));
  fireEvent.click(within(choice).getByRole('button', { name: 'Use none of these' }));
  expect(onChoose.mock.calls).toEqual([[key(1)], [null]]);
  cleanup();
  // A complete comparison says nothing about it.
  mount(view({ candidates: [candidate(1)], disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false } }));
  expect(screen.queryByText(/not every release MusicBrainz found/i)).not.toBeInTheDocument();
  cleanup();
  // Once a release or none is applied for this run, nothing is offered: the release is marked in the folded list.
  for (const [choice, candidateKey] of [['chosen', key(1)], ['none', null]] as const) {
    mount(view({ candidates: [candidate(1)], groups: [group(1, [[1, 1, 'First']])], applied: { ...applied(2, candidateKey)!, choice }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
    expect(screen.queryByRole('region')).not.toBeInTheDocument();
    cleanup();
  }
});

test('a release applied as a preselection stays choosable when a re-rank leaves a tie, so it can be confirmed as the choice', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] },
    applied: { ...applied(2, key(1))!, choice: 'preselected', basis: 'onlyMatchingGroup' }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  const [first] = within(tie).getAllByRole('listitem');
  expect(within(first).getByRole('button', { name: 'Use this release' })).toBeEnabled();
  fireEvent.click(within(first).getByRole('button', { name: 'Use this release' }));
  expect(onChoose).toHaveBeenCalledWith(key(1));
  expect(screen.queryByRole('button', { name: 'Applied' })).not.toBeInTheDocument();
});

test('a tie from a partial comparison keeps the several-releases heading and says not every release was compared; without a choice the line stands beside the folded list', () => {
  const partial = { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true };
  const line = 'Not every release MusicBrainz found was compared with these files, so a matching release may be missing from this list.';
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] }, disclosure: partial }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  expect(within(tie).getByText(line)).toBeInTheDocument();
  expect(screen.queryByRole('region', { name: /^One release matches/ })).not.toBeInTheDocument();
  cleanup();
  // A release applied by its shared identifier needs no choice, and the partial comparison is still said.
  mount(view({ candidates: [candidate(1)], groups: [group(1, [[1, 1, 'First']])], preselection: { candidateKey: key(1), basis: 'releaseId', artistMismatch: false, notChecked: false },
    applied: { ...applied(2, key(1))!, choice: 'preselected', basis: 'releaseId' }, disclosure: partial }));
  expect(screen.queryByRole('region')).not.toBeInTheDocument();
  expect(screen.getByText(line)).toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Applied' })).toBeDisabled();
});

test('groups that differ only by the MusicBrainz artist or label they credit show each ID beside the names', () => {
  const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, tracks: [number, number, string][] = [[1, 1, 'First'], [1, 2, 'Second']];
  const credited = (n: number, artist: string, label: string) => { const value = group(n, tracks); value.proposal.artists = value.proposal.artists.map(entry => ({ ...entry, musicBrainzId: artist })); value.proposal.labelMusicBrainzId = label; return value; };
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [credited(1, id(1), id(9)), credited(2, id(2), id(9))], needsAnswer: { tie: true, conflicts: [] } }));
  const [first, second] = within(screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' })).getAllByRole('listitem');
  expect([...first.querySelectorAll('dt')].map(term => term.textContent)[0]).toBe('Artists');
  expect(first.querySelector('dd')!.textContent).toBe(`Synthetic Lead · MusicBrainz ID ${id(1)}`);
  expect(second.querySelector('dd')!.textContent).toBe(`Synthetic Lead · MusicBrainz ID ${id(2)}`);
  cleanup();
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [credited(1, id(1), id(8)), credited(2, id(1), id(9))], needsAnswer: { tie: true, conflicts: [] } }));
  const [labelled] = within(screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' })).getAllByRole('listitem');
  expect(labelled.querySelector('dd')!.textContent).toBe(`Label · MusicBrainz ID ${id(8)}`);
});

test('a release reporting front artwork shows it once through the protected preview of this import: in the tie view, else in the folded list once opened', async () => {
  mount(view({ candidates: [candidate(1, { artwork: true }), candidate(2), candidate(3, { artwork: true, status: 'notMatching', groupKey: null })], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])],
    needsAnswer: { tie: true, conflicts: [] } }));
  const previews = () => screen.queryAllByRole('img', { name: 'Front artwork of this release' }) as HTMLImageElement[];
  // Candidate 1 represents its group in the tie view, so only that preview loads; the closed folded list loads none.
  await waitFor(() => expect(previews()).toHaveLength(1));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  expect(within(tie).getByRole('img').getAttribute('src')).toBe(`/api/admin/v1/imports/${importId}/lookup/candidates/${encodeURIComponent(key(1))}/artwork?viewer=${viewerId}`);
  expect(previews()[0].getAttribute('src')).toContain('musicbrainz%3A');
  expect([previews()[0].getAttribute('loading'), previews()[0].getAttribute('decoding'), previews()[0].getAttribute('width'), previews()[0].getAttribute('height')]).toEqual([null, 'async', '64', '64']);
  // Opening the folded list loads candidate 3's preview there; candidate 1's is not repeated.
  unfold(screen.getByText('Releases found: 3'));
  await waitFor(() => expect(previews()).toHaveLength(2));
  expect(previews()[1].getAttribute('src')).toContain(encodeURIComponent(key(3)));
});

test('previews load two at a time in the order shown, and one that fails is tried once more after two seconds and then hidden', async () => {
  vi.useFakeTimers();
  try {
    mount(view({ candidates: Array.from({ length: 8 }, (_, index) => candidate(index + 1, { artwork: true })) }));
    const previews = () => screen.queryAllByRole('img', { name: 'Front artwork of this release' }) as HTMLImageElement[];
    const of = (n: number) => previews().find(image => image.getAttribute('src')!.includes(encodeURIComponent(key(n))));
    const loaded = new Set<HTMLImageElement>(), inFlight = () => previews().filter(image => !loaded.has(image)).map(image => key(Number(image.getAttribute('src')!.match(/0000000(\d)\/artwork/)![1])));
    const load = (n: number) => { const image = of(n)!; loaded.add(image); fireEvent.load(image); };
    // Nothing loads while the folded list is closed; opening it starts the first two.
    expect(previews()).toHaveLength(0);
    unfold(screen.getByText('Releases found: 8'));
    expect(inFlight()).toEqual([key(1), key(2)]);
    load(1); expect(inFlight()).toEqual([key(2), key(3)]);
    // Preview 2 is refused (as a busy server answers 429): it leaves, and the next one takes its turn.
    const refused = of(2)!; fireEvent.error(refused);
    expect(of(2)).toBeUndefined(); expect(inFlight()).toEqual([key(3), key(4)]);
    // Two seconds later it waits for the next free turn, ahead of those after it, as a new image element.
    act(() => { vi.advanceTimersByTime(2_000); });
    expect(inFlight()).toEqual([key(3), key(4)]);
    load(3); expect(inFlight()).toEqual([key(2), key(4)]); expect(of(2)).not.toBe(refused);
    // Its one retry fails too: it is hidden for good.
    fireEvent.error(of(2)!); act(() => { vi.advanceTimersByTime(10_000); });
    expect(of(2)).toBeUndefined(); expect(inFlight()).toEqual([key(4), key(5)]);
    for (const n of [4, 5, 6, 7, 8]) { expect(inFlight().length).toBeLessThanOrEqual(2); load(n); }
    expect([inFlight(), previews().length]).toEqual([[], 7]);
  } finally { vi.useRealTimers(); }
});

test('an iTunes-only candidate is marked as such, and as not checked against MusicBrainz when it was not, and previews through its own encoded key', () => {
  const itunes = (n: number, notChecked: boolean) => candidate(n, { key: `itunes:16893585${n}`, releaseId: `16893585${n}`, source: 'itunes', notChecked, label: null, artwork: true });
  mount(view({ candidates: [itunes(1, true), itunes(2, false), candidate(3)] }));
  unfold(screen.getByText('Releases found: 3'));
  const [unchecked, checked, musicBrainz] = screen.getAllByRole('listitem').filter(item => item.querySelector('strong'));
  expect(within(unchecked).getByText('iTunes only · Not checked against MusicBrainz')).toBeInTheDocument();
  expect(within(checked).getByText('iTunes only')).toBeInTheDocument();
  expect(within(musicBrainz).queryByText(/iTunes only/)).toBeNull();
  expect(within(unchecked).getByRole('img').getAttribute('src')).toBe(`/api/admin/v1/imports/${importId}/lookup/candidates/itunes%3A168935851/artwork?viewer=${viewerId}`);
});

const reviewTracks = [{ slotId: '10000000-0000-4000-8000-000000000001', title: 'Synthetic first track' }, { slotId: '10000000-0000-4000-8000-000000000002', title: '' }];
type ReviewCandidate = ReviewLookupView['candidates'][number];
const subset = (extra: Partial<NonNullable<NonNullable<ReviewCandidate['comparison']>['subset']>> = {}) => ({ leftOutTracks: 0, pairing: 'unique' as const,
  pairs: [{ slotId: reviewTracks[0].slotId, discNumber: 1, trackNumber: 1 }, { slotId: reviewTracks[1].slotId, discNumber: 1, trackNumber: 3 }], missingTrackCount: 1, unpairableSlotIds: [], ...extra });
const reviewCandidate = (n: number, extra: Partial<ReviewCandidate> = {}): ReviewCandidate => ({ ...candidate(n), comparison: { ...comparison(), trackCount: { local: 2, candidate: 3 }, subset: subset() }, ...extra } as ReviewCandidate);
/** A review's view: the import view's fields with review candidates and the catalog trigger admitted. */
const reviewView = (extra: Partial<ReviewLookupView> = {}): ReviewLookupView => ({ ...view(), candidates: [], applied: null, ...extra }) as ReviewLookupView;
function mountReview(lookup: ReviewLookupView) { const onChoose = vi.fn(); render(<CandidateChooser projectId={importId} viewerId={viewerId} lookup={lookup} review={{ tracks: reviewTracks }} disabled={false} onChoose={onChoose} />); return onChoose; }

test('an existing-Album review candidate shows the members it pairs, the missing-file rows it adds, tracks left out and members no track can pair with', () => {
  mountReview(reviewView({ input: { trigger: 'catalog', submitted: null }, candidates: [reviewCandidate(1, { artwork: true }),
    reviewCandidate(2, { status: 'notMatching', groupKey: null, comparison: { ...comparison(), differences: ['pairing', 'tooManyTracks', 'tracklistInvalid'], trackCount: { local: 2, candidate: 120 },
      subset: subset({ pairing: 'none', pairs: [], missingTrackCount: null, leftOutTracks: 3, unpairableSlotIds: [reviewTracks[1].slotId] }) } })] }));
  unfold(screen.getByText('Releases found: 2'));
  const [paired, unpairable] = screen.getAllByRole('listitem').filter(item => item.querySelector('strong'));
  expect(within(paired).getByText('Matches this Album\'s tracks · Label 1 · 2021-05 · 2 tracks')).toBeInTheDocument();
  expect(within(paired).getByText('Tracks paired: 2 of 2')).toBeInTheDocument();
  expect(within(paired).getByText('1 · Synthetic first track → Disc 1 · Track 1')).toBeInTheDocument();
  expect(within(paired).getByText('2 · — → Disc 1 · Track 3')).toBeInTheDocument();
  expect(within(paired).getByText('Adds 1 missing-file row')).toBeInTheDocument();
  expect(within(paired).queryByText(/left out/)).not.toBeInTheDocument();
  expect(within(unpairable).getByText('Does not match this Album\'s tracks · Label 2 · 2021-05 · 2 tracks')).toBeInTheDocument();
  expect(within(unpairable).getByText('Tracks paired: 0 of 2')).toBeInTheDocument();
  expect(within(unpairable).queryByText(/missing-file/)).not.toBeInTheDocument();
  expect(within(unpairable).getByText('Video or data tracks left out: 3')).toBeInTheDocument();
  expect(within(unpairable).getByText('No track of this release can pair with: 2 · —')).toBeInTheDocument();
  expect(within(unpairable).getAllByRole('listitem').map(item => item.textContent).slice(-3)).toEqual(['This Album\'s tracks do not pair with this release in exactly one way',
    'The release has more audio tracks than an expected tracklist can hold (100)', 'The release\'s tracklist cannot be kept as an expected tracklist']);
  // Previews come from the review, never from the import routes.
  expect(within(paired).getByRole('img').getAttribute('src')).toBe(`/api/admin/v1/catalog-reviews/${importId}/lookup/candidates/${encodeURIComponent(key(1))}/artwork?viewer=${viewerId}`);
});

test('a review tie, the offered single choice, unverified releases and the disclosures speak of the Album\'s tracks; an import keeps its file wording', () => {
  const tie = reviewView({ candidates: [reviewCandidate(1), reviewCandidate(2, { status: 'unverified' })], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])],
    needsAnswer: { tie: true, conflicts: [] }, disclosure: { unknownLocalDurations: 1, unknownLocalDiscNumbers: 2, partialComparison: true } });
  const onChoose = mountReview(tie);
  const region = screen.getByRole('region', { name: 'Several releases match this Album\'s tracks. Choose one, or none.' });
  expect(within(region).getByText('Tracks with an unknown duration: 1. A release they pair with stays unverified.')).toBeInTheDocument();
  expect(within(region).getByText('Tracks without a disc number: 2. They can pair with a track on any disc.')).toBeInTheDocument();
  expect(within(region).getByText('Not every release MusicBrainz found was compared with this Album\'s tracks, so a matching release may be missing from this list.')).toBeInTheDocument();
  expect(within(region).getAllByText('Tracks paired: 2 of 2')).toHaveLength(2);
  fireEvent.click(within(region).getByRole('button', { name: 'Use none of these' })); expect(onChoose).toHaveBeenCalledWith(null);
  unfold(screen.getByText('Releases found: 2'));
  expect(screen.getByText(/^Not verified: the tracks pair with it in more than one way/)).toBeInTheDocument();
  cleanup();
  mountReview(reviewView({ candidates: [reviewCandidate(1)], groups: [group(1, [[1, 1, 'First']])], disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  expect(screen.getByRole('region', { name: /^One release matches this Album's tracks but was not applied/ })).toBeInTheDocument();
  cleanup();
  mount(view({ candidates: [candidate(1)], groups: [group(1, [[1, 1, 'First']])], disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  expect(screen.getByRole('region', { name: /^One release matches these files but was not applied/ })).toBeInTheDocument();
  expect(screen.queryByText(/Tracks paired/)).not.toBeInTheDocument();
});

test('a review release first found through a track title is marked so in the tie view, the offered single choice and the folded list; another release and any import candidate are not', () => {
  const marked = 'Found through a track title';
  mountReview(reviewView({ candidates: [reviewCandidate(1, { byTrackTitle: true }), reviewCandidate(2, { byTrackTitle: false })], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])],
    needsAnswer: { tie: true, conflicts: [] } }));
  const region = screen.getByRole('region', { name: 'Several releases match this Album\'s tracks. Choose one, or none.' });
  const [byTitle, other] = within(region).getAllByRole('listitem').filter(item => item.querySelector('strong'));
  expect(within(byTitle).getByText(marked)).toBeInTheDocument();
  expect(within(other).queryByText(marked)).toBeNull();
  unfold(screen.getByText('Releases found: 2'));
  expect(screen.getAllByText(marked)).toHaveLength(2);
  cleanup();
  mountReview(reviewView({ candidates: [reviewCandidate(1, { byTrackTitle: true })], groups: [group(1, [[1, 1, 'First']])],
    disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  expect(within(screen.getByRole('region', { name: /^One release matches this Album's tracks but was not applied/ })).getByText(marked)).toBeInTheDocument();
  cleanup();
  // An import view never carries the key; even a candidate given one is not marked outside a review.
  mount(view({ candidates: [{ ...candidate(1), byTrackTitle: true } as Candidate] }));
  unfold(screen.getByText('Releases found: 1'));
  expect(screen.queryByText(marked)).toBeNull();
});
